package io.github.diodeme.ji.telemetry;

import java.util.Map;

/** Callback-owned span and explicit child context. Recording methods are passive and non-throwing. */
public interface TelemetrySpan extends TelemetryContext {
    void setAttributes(Map<String, TelemetryValue> attributes);

    void addEvent(String name, Map<String, TelemetryValue> attributes);

    void recordMetric(MetricPoint point);

    void setStatus(SpanStatus status);

    void settle(boolean failed);

    SpanParent childParent();
}
